var APPS_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbwbSo-gBTkVG99dqir2vax9gE8FuY73Q1hgc0FDpY9ZtLQCkt1_VGE2FIe24UDdPmCt/exec';

function showSyncStatus(msg, type) {
  var bar = document.getElementById('last-update');
  if (!bar) return;
  var colors = { ok: 'var(--green)', err: 'var(--red)', loading: 'var(--amber)' };
  bar.style.color = colors[type] || 'var(--text2)';
  bar.textContent = msg;
}

function loadFromSheet() {
  if (!APPS_SCRIPT_URL || APPS_SCRIPT_URL === 'REEMPLAZAR_CON_TU_URL') {
    renderAll();
    return;
  }
  showSyncStatus('Cargando datos desde Google Sheets...', 'loading');
  fetch(APPS_SCRIPT_URL)
    .then(function(r) { return r.json(); })
    .then(function(res) {
      if (res.error) throw new Error(res.error);
      var sheetData = res.data;
      var hasData = sheetData && Object.keys(sheetData).length > 0;
      var hasRealPCs = false;
      if (hasData) {
        // Verificar que realmente haya PCs (no solo claves vacías)
        Object.keys(sheetData).forEach(function(aula) {
          if (sheetData[aula] && sheetData[aula].length > 0) hasRealPCs = true;
        });
      }
      if (hasRealPCs) {
        DB = sheetData;
        activeAula = Object.keys(DB)[0];
        showSyncStatus('Sincronizado con Google Sheets · ' + new Date().toLocaleTimeString('es-AR'), 'ok');
        renderAll();
      } else {
        // Sheet vacío o sin datos reales — usar datos locales y subirlos
        showSyncStatus('Sheet vacío — subiendo datos locales...', 'loading');
        renderAll();
        saveToSheet(false);
      }
    })
    .catch(function(e) {
      showSyncStatus('Sin conexión al Sheet — usando datos locales', 'err');
      renderAll();
    });
}

function saveToSheet(silent) {
  if (!APPS_SCRIPT_URL || APPS_SCRIPT_URL === 'REEMPLAZAR_CON_TU_URL') return;
  if (!silent) showSyncStatus('Guardando en Google Sheets...', 'loading');
  fetch(APPS_SCRIPT_URL, {
    method: 'POST',
    body: JSON.stringify({ action: 'save', data: DB })
  })
  .then(function(r) { return r.json(); })
  .then(function(res) {
    if (res.error) throw new Error(res.error);
    if (!silent) {
      showSyncStatus('Guardado en Google Sheets · ' + new Date().toLocaleTimeString('es-AR'), 'ok');
      toast('Guardado en Google Sheets', 'ok');
    }
  })
  .catch(function(e) {
    if (!silent) {
      showSyncStatus('Error al guardar: ' + e.message, 'err');
      toast('Error al guardar en Sheet', 'err');
    }
  });
}



