let HISTORY=[];
let activeAula='';
let editIdx=null,editAula=null,currentPage='dashboard';
const CC=['#6366f1','#34d399','#fbbf24','#f472b6','#8b5cf6','#2dd4bf'];

function allPCs(){return Object.values(DB).flat();}
function isOp(pc){return pc.estado==='Operativa';}

function switchPage(p,el){
  document.querySelectorAll('.page').forEach(function(x){x.classList.remove('active');});
  document.querySelectorAll('.nav-tab').forEach(function(x){x.classList.remove('active');});
  document.getElementById('page-'+p).classList.add('active');
  el.classList.add('active');
  currentPage=p;
  if(p==='inventario'){renderTabs();renderTable();}
  if(p==='alertas')renderAlerts();
  if(p==='historial')renderHistory();
}

function renderMetrics(){
  var all=allPCs(),total=all.length,op=all.filter(isOp).length,noOp=total-op;
  var ssd=all.filter(function(p){return p.disco_tipo&&p.disco_tipo.startsWith('SSD');}).length;
  var pct=Math.round(op/total*100);
  document.getElementById('metrics').innerHTML=
    '<div class="metric-card blue"><div class="metric-icon">&#128187;</div><div class="metric-value">'+total+'</div><div class="metric-label">Total PCs</div></div>'+
    '<div class="metric-card green"><div class="metric-icon">&#9989;</div><div class="metric-value">'+op+'</div><div class="metric-label">Operativas</div></div>'+
    '<div class="metric-card red"><div class="metric-icon">&#9888;</div><div class="metric-value">'+noOp+'</div><div class="metric-label">No operativas</div></div>'+
    '<div class="metric-card teal"><div class="metric-icon">&#128190;</div><div class="metric-value">'+ssd+'</div><div class="metric-label">Con SSD</div></div>'+
    '<div class="metric-card amber"><div class="metric-icon">&#127EB;</div><div class="metric-value">'+Object.keys(DB).length+'</div><div class="metric-label">Aulas/Salas</div></div>'+
    '<div class="metric-card pink"><div class="metric-icon">&#128202;</div><div class="metric-value">'+pct+'%</div><div class="metric-label">Disponibilidad</div></div>';
  document.getElementById('badge-op').textContent=op+' / '+total+' activas';
  document.getElementById('last-update').textContent='Actualizado: '+new Date().toLocaleString('es-AR');
}

var cA,cR,cC2,cD;
function renderCharts(){
  var aulas=Object.keys(DB);
  if(cA)cA.destroy();
  cA=new Chart(document.getElementById('chartAula'),{type:'bar',data:{labels:aulas,datasets:[
    {label:'Op',data:aulas.map(function(a){return DB[a].filter(isOp).length;}),backgroundColor:'#6366f1',borderRadius:6},
    {label:'No op',data:aulas.map(function(a){return DB[a].filter(function(p){return !isOp(p);}).length;}),backgroundColor:'#fb7185',borderRadius:6}
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{color:'rgba(255,255,255,0.03)'},ticks:{color:'#71717a'}},y:{grid:{color:'rgba(255,255,255,0.03)'},ticks:{color:'#71717a',stepSize:1}}}}});

  var ramC={};
  allPCs().filter(isOp).forEach(function(p){if(p.ram_gb&&p.ram_gb!=='—'){var k=p.ram_gb+' GB';ramC[k]=(ramC[k]||0)+1;}});
  var rL=Object.keys(ramC).sort(function(a,b){return parseInt(a)-parseInt(b);});
  document.getElementById('legend-ram').innerHTML=rL.map(function(l,i){return '<div class="legend-item"><span class="legend-dot" style="background:'+CC[i%6]+'"></span>'+l+' ('+ramC[l]+')</div>';}).join('');
  if(cR)cR.destroy();
  cR=new Chart(document.getElementById('chartRAM'),{type:'doughnut',data:{labels:rL,datasets:[{data:rL.map(function(k){return ramC[k];}),backgroundColor:CC,borderWidth:0,hoverOffset:4}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},cutout:'65%'}});

  var cpuC={};
  allPCs().filter(isOp).forEach(function(p){
    if(!p.cpu||p.cpu==='—')return;
    var k=p.cpu.replace(/ with Radeon Graphics$/,'').replace(/ RADEON R7, 10 Compute Cores 4C\+6G$/,'').replace(/ Radeon R5, 6 Compute Cores 2C\+4G$/,'').replace(/ APU with Radeon\(tm\) HD Graphics$/,'').trim();
    cpuC[k]=(cpuC[k]||0)+1;
  });
  var cpuS=Object.entries(cpuC).sort(function(a,b){return b[1]-a[1];}).slice(0,6);
  document.getElementById('cpuWrap').style.height=Math.max(200,cpuS.length*40+50)+'px';
  if(cC2)cC2.destroy();
  cC2=new Chart(document.getElementById('chartCPU'),{type:'bar',data:{labels:cpuS.map(function(e){return e[0];}),datasets:[{data:cpuS.map(function(e){return e[1];}),backgroundColor:CC,borderRadius:5}]},options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{color:'rgba(255,255,255,0.03)'},ticks:{color:'#71717a',stepSize:1}},y:{grid:{display:false},ticks:{color:'#a1a1aa',font:{size:11}}}}}});

  if(cD)cD.destroy();
  cD=new Chart(document.getElementById('chartDisco'),{type:'bar',data:{labels:aulas,datasets:[
    {label:'SSD',data:aulas.map(function(a){return DB[a].filter(function(p){return p.disco_tipo&&p.disco_tipo.startsWith('SSD');}).length;}),backgroundColor:'#2dd4bf',borderRadius:5},
    {label:'HDD',data:aulas.map(function(a){return DB[a].filter(function(p){return p.disco_tipo==='HDD';}).length;}),backgroundColor:'#52525b',borderRadius:5}
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{stacked:true,grid:{color:'rgba(255,255,255,0.03)'},ticks:{color:'#71717a'}},y:{stacked:true,grid:{color:'rgba(255,255,255,0.03)'},ticks:{color:'#71717a',stepSize:1}}}}});
}

function renderTabs(){
  document.getElementById('tabs').innerHTML=Object.keys(DB).map(function(a){
    return '<button class="tab '+(a===activeAula?'active':'')+'" onclick="switchAulaTab(\''+a+'\')">'+a+'</button>';
  }).join('');
}
function switchAulaTab(a){activeAula=a;renderTabs();renderTable();}

function applyFilters(){
  var q=document.getElementById('search-input').value.toLowerCase();
  var fE=document.getElementById('filter-estado').value;
  var fR=document.getElementById('filter-ram').value;
  var fD=document.getElementById('filter-disco').value;
  var pcs=DB[activeAula].map(function(pc,i){return {pc:pc,i:i};});
  if(q)pcs=pcs.filter(function(x){return [x.pc.cpu,x.pc.disco_modelo,x.pc.estado,x.pc.observaciones].some(function(v){return v&&String(v).toLowerCase().includes(q);});});
  if(fE)pcs=pcs.filter(function(x){return fE==='NO ANDA'?!isOp(x.pc):x.pc.estado===fE;});
  if(fR)pcs=pcs.filter(function(x){return String(x.pc.ram_gb)===fR;});
  if(fD)pcs=pcs.filter(function(x){return x.pc.disco_tipo&&x.pc.disco_tipo.includes(fD);});
  document.getElementById('filter-count').textContent=pcs.length+' resultado'+(pcs.length!==1?'s':'');
  document.getElementById('inv-tbody').innerHTML=pcs.map(function(x){
    var pc=x.pc,i=x.i;
    var op=isOp(pc);
    var ssd=pc.disco_tipo&&pc.disco_tipo.startsWith('SSD');
    return '<tr>'+
      '<td class="td-num">'+pc.n+'</td>'+
      '<td><span class="badge '+(op?'badge-ok':'badge-bad')+'">'+(op?'Operativa':'No operativa')+'</span></td>'+
      '<td class="td-cpu">'+(pc.cpu||'—')+'</td>'+
      '<td class="td-bold">'+(pc.ram_gb!=='—'?pc.ram_gb+' GB '+pc.tipo_ram:'—')+'</td>'+
      '<td><span class="disk-badge '+(ssd?'disk-ssd':'disk-hdd')+'">'+(pc.disco_tipo||'—')+'</span></td>'+
      '<td class="td-num">'+(pc.disco_cap!=='—'?pc.disco_cap+' GB':'—')+'</td>'+
      '<td class="td-obs" title="'+(pc.observaciones||'')+'">'+(pc.observaciones||'—')+'</td>'+
      '<td>'+
        '<button class="action-btn" onclick="editPC(\''+activeAula+'\','+i+')">&#9998;</button>'+
        '<button class="action-btn del" onclick="deletePC(\''+activeAula+'\','+i+')">&#128465;</button>'+
      '</td>'+
    '</tr>';
  }).join('');
}
function clearFilters(){
  document.getElementById('search-input').value='';
  document.getElementById('filter-estado').value='';
  document.getElementById('filter-ram').value='';
  document.getElementById('filter-disco').value='';
  applyFilters();
}
function renderTable(){
  document.getElementById('inv-thead').innerHTML='<tr><th>N</th><th>Estado</th><th>CPU</th><th>RAM</th><th>Disco</th><th>Cap.</th><th>Observaciones</th><th>Acciones</th></tr>';
  applyFilters();
}

function getAlerts(){
  var alerts=[];
  Object.keys(DB).forEach(function(aula){
    var pcs=DB[aula];
    pcs.forEach(function(pc){
      if(!isOp(pc)){
        alerts.push({level:'high',icon:'&#128308;',title:'PC '+pc.n+' no operativa — '+aula,desc:pc.estado+(pc.observaciones?'\n'+pc.observaciones:''),meta:aula,aula:aula,idx:pcs.indexOf(pc)});
      } else {
        var b=parseFloat(String(pc.vel_base).replace(',','.')),a2=parseFloat(String(pc.vel_actual).replace(',','.'));
        if(!isNaN(b)&&!isNaN(a2)&&a2<b*0.6){
          alerts.push({level:'high',icon:'&#9889;',title:'PC '+pc.n+' — velocidad muy baja ('+pc.vel_actual+' GHz)',desc:'Base: '+pc.vel_base+' → Actual: '+pc.vel_actual+' GHz',meta:aula,aula:aula,idx:pcs.indexOf(pc)});
        }
        if(typeof pc.ram_gb==='number'&&pc.ram_gb<=4){
          alerts.push({level:'med',icon:'&#128993;',title:'PC '+pc.n+' — RAM baja ('+pc.ram_gb+' GB)',desc:pc.ram_gb+' GB puede ser insuficiente para uso escolar.',meta:aula,aula:aula,idx:pcs.indexOf(pc)});
        }
        if(pc.observaciones&&pc.observaciones.trim()){
          alerts.push({level:'med',icon:'&#128221;',title:'PC '+pc.n+' — tiene observaciones',desc:pc.observaciones,meta:aula,aula:aula,idx:pcs.indexOf(pc)});
        }
      }
    });
  });
  return alerts;
}
function renderAlerts(){
  var alerts=getAlerts();
  document.getElementById('alerts-badge').textContent=alerts.length+(alerts.length===1?' alerta':' alertas');
  var b=document.getElementById('alert-count-badge');
  if(alerts.length>0){b.style.display='inline';b.textContent=alerts.length;}else{b.style.display='none';}
  if(alerts.length===0){
    document.getElementById('alerts-grid').innerHTML='<div class="no-alerts"><div style="font-size:36px;margin-bottom:10px;">&#9989;</div><div style="font-weight:600;margin-bottom:5px;">Todo en orden</div><div style="font-size:12px;">No se detectaron alertas.</div></div>';
    return;
  }
  document.getElementById('alerts-grid').innerHTML=alerts.map(function(a){
    return '<div class="alert-card '+a.level+'">'+
      '<div class="alert-icon">'+a.icon+'</div>'+
      '<div>'+
        '<div class="alert-title">'+a.title+'</div>'+
        '<div class="alert-desc">'+a.desc+'</div>'+
        '<div class="alert-meta">'+a.meta+' &middot; <button style="background:none;border:none;color:var(--accent);font-size:10px;cursor:pointer;padding:0;" onclick="goEdit(\''+a.aula+'\','+a.idx+')">Ver PC &rarr;</button></div>'+
      '</div>'+
    '</div>';
  }).join('');
}
function goEdit(aula,idx){
  activeAula=aula;
  switchPage('inventario',document.querySelectorAll('.nav-tab')[1]);
  setTimeout(function(){editPC(aula,idx);},100);
}

function addHistory(action,detail,type){
  if(!type)type='edit';
  HISTORY.unshift({action:action,detail:detail,type:type,time:new Date().toLocaleString('es-AR')});
  if(HISTORY.length>100)HISTORY.pop();
  if(currentPage==='historial')renderHistory();
}
function renderHistory(){
  if(HISTORY.length===0){
    document.getElementById('history-list').innerHTML='<div style="text-align:center;padding:40px;color:var(--text3);font-size:13px;">&#128203; Aun no hay cambios registrados.</div>';
    return;
  }
  document.getElementById('history-list').innerHTML=HISTORY.map(function(h){
    return '<div class="history-item"><div class="history-dot '+h.type+'"></div><div style="flex:1;"><div class="history-action">'+h.action+'</div><div style="font-size:11px;color:var(--text2);margin:2px 0;">'+h.detail+'</div><div style="font-size:11px;color:var(--text3);">'+h.time+'</div></div></div>';
  }).join('');
}
function clearHistory(){if(confirm('Limpiar todo el historial?')){HISTORY=[];renderHistory();toast('Historial limpiado','info');}}

function editPC(aula,idx){
  editAula=aula;editIdx=idx;
  var pc=DB[aula][idx];
  document.getElementById('modal-title').textContent='Editar PC '+pc.n;
  document.getElementById('modal-sub').textContent=aula;
  buildFields(pc);
  document.getElementById('modal-edit').classList.add('open');
}
function openAddPC(){
  editAula=activeAula;editIdx=null;
  document.getElementById('modal-title').textContent='Nueva PC';
  document.getElementById('modal-sub').textContent=activeAula;
  var newN=Math.max.apply(null,[0].concat(DB[activeAula].map(function(p){return p.n||0;})))+1;
  buildFields({n:newN});
  document.getElementById('modal-edit').classList.add('open');
}
function buildFields(pc){
  document.getElementById('modal-fields').innerHTML=FIELDS.map(function(f){
    var val=pc[f.k]!==undefined?pc[f.k]:'';
    var input='';
    if(f.t==='select'){
      input='<select id="ff_'+f.k+'">'+f.opts.map(function(o){return '<option'+(val===o?' selected':'')+'>'+o+'</option>';}).join('')+'</select>';
    } else if(f.t==='textarea'){
      input='<textarea id="ff_'+f.k+'">'+val+'</textarea>';
    } else {
      input='<input type="'+f.t+'" id="ff_'+f.k+'" value="'+val+'">';
    }
    return '<div class="form-group'+(f.full?' full':'')+'"><label>'+f.l+'</label>'+input+'</div>';
  }).join('');
}
function savePC(){
  var pc={};
  FIELDS.forEach(function(f){
    var el=document.getElementById('ff_'+f.k);
    pc[f.k]=f.t==='number'?(parseFloat(el.value)||el.value):el.value;
  });
  if(editIdx===null){
    DB[editAula].push(pc);
    addHistory('PC '+pc.n+' agregada en '+editAula,'CPU: '+(pc.cpu||'—')+' · RAM: '+pc.ram_gb+' GB','add');
    toast('PC agregada','ok');
  } else {
    var old=DB[editAula][editIdx];
    var ch=FIELDS.filter(function(f){return String(old[f.k])!==String(pc[f.k]);}).map(function(f){return f.l+': "'+old[f.k]+'" → "'+pc[f.k]+'"';}).join('; ');
    DB[editAula][editIdx]=pc;
    addHistory('PC '+pc.n+' editada en '+editAula,ch||'Sin cambios','edit');
    toast('PC guardada','ok');
  }
  closeModal('modal-edit');
  renderAll();
  saveToSheet(false);
}
function deletePC(aula,idx){
  var pc=DB[aula][idx];
  if(!confirm('Eliminar PC '+pc.n+' de '+aula+'?'))return;
  DB[aula].splice(idx,1);
  addHistory('PC '+pc.n+' eliminada de '+aula,'CPU: '+(pc.cpu||'—'),'del');
  renderAll();
  toast('PC eliminada','ok');
  saveToSheet(false);
}

function openImport(){document.getElementById('modal-import').classList.add('open');}
function closeModal(id){document.getElementById(id).classList.remove('open');}

