function openTransfer() {
  var aulas = Object.keys(DB);
  // Poblar selects de origen y destino
  var fromSel = document.getElementById('transfer-from');
  var toSel   = document.getElementById('transfer-to');
  fromSel.innerHTML = aulas.map(function(a){ return '<option value="'+a+'">'+a+'</option>'; }).join('');
  toSel.innerHTML   = aulas.map(function(a){ return '<option value="'+a+'">'+a+'</option>'; }).join('');
  // Destino por defecto diferente al origen
  if (aulas.length > 1) toSel.value = aulas[1];
  updateTransferFrom();
  document.getElementById('modal-transfer').classList.add('open');
}

function updateTransferFrom() {
  var aula = document.getElementById('transfer-from').value;
  // Asegurarse que destino sea distinto
  var toSel = document.getElementById('transfer-to');
  if (toSel.value === aula) {
    var aulas = Object.keys(DB);
    toSel.value = aulas.find(function(a){ return a !== aula; }) || aulas[0];
  }
  renderTransferList();
  updateTransferPreview();
}

function renderTransferList() {
  var aula = document.getElementById('transfer-from').value;
  var pcs  = DB[aula] || [];
  var list = document.getElementById('transfer-pc-list');
  if (pcs.length === 0) {
    list.innerHTML = '<div style="padding:20px;text-align:center;font-size:12px;color:var(--text3);">No hay PCs en esta aula</div>';
    return;
  }
  var html = '';
  pcs.forEach(function(pc, i) {
    var op = pc.estado === 'Operativa';
    var badgeClass = op ? 'badge-ok' : 'badge-bad';
    var badgeText = op ? 'Operativa' : 'No operativa';
    var cpu = (pc.cpu || '—')
      .replace(/ with Radeon Graphics$/, '')
      .replace(/ RADEON R7.*$/, '')
      .replace(/ Radeon R5.*$/, '')
      .replace(/ APU with.*$/, '')
      .trim();
    html += '<div class="transfer-pc-item" data-idx="' + i + '" id="tpc-item-' + i + '">';
    html += '<input type="checkbox" class="transfer-checkbox" id="tpc-' + i + '">';
    html += '<div class="transfer-pc-info">';
    html += '<div class="transfer-pc-num">PC ' + pc.n + '</div>';
    html += '<div class="transfer-pc-cpu">' + cpu + ' &middot; ' + pc.ram_gb + ' GB</div>';
    html += '</div>';
    html += '<span class="transfer-pc-badge ' + badgeClass + '">' + badgeText + '</span>';
    html += '</div>';
  });
  list.innerHTML = html;

  // Attach click handlers after rendering
  list.querySelectorAll('.transfer-pc-item').forEach(function(item) {
    item.addEventListener('click', function() {
      var idx = parseInt(this.getAttribute('data-idx'));
      var cb = document.getElementById('tpc-' + idx);
      cb.checked = !cb.checked;
      this.classList.toggle('selected', cb.checked);
      updateTransferCount();
      updateTransferPreview();
    });
    var cb = item.querySelector('.transfer-checkbox');
    cb.addEventListener('click', function(e) {
      e.stopPropagation();
      var idx = parseInt(item.getAttribute('data-idx'));
      item.classList.toggle('selected', this.checked);
      updateTransferCount();
      updateTransferPreview();
    });
  });

  updateTransferCount();
  updateTransferPreview();
}


function getSelectedIndices() {
  var checkboxes = document.querySelectorAll('#transfer-pc-list .transfer-checkbox');
  var selected = [];
  checkboxes.forEach(function(cb, i){ if (cb.checked) selected.push(i); });
  return selected;
}

function updateTransferCount() {
  var n = getSelectedIndices().length;
  document.getElementById('transfer-sel-count').textContent = n + ' seleccionada' + (n !== 1 ? 's' : '');
  document.getElementById('transfer-confirm-btn').disabled = n === 0;
  updateTransferSummary();
}

function updateTransferPreview() {
  var fromAula = document.getElementById('transfer-from').value;
  var toAula   = document.getElementById('transfer-to').value;
  var selected = getSelectedIndices();
  var pcs = DB[fromAula] || [];
  var preview = document.getElementById('transfer-dest-preview');

  if (selected.length === 0) {
    preview.innerHTML = '<div class="transfer-dest-empty">Seleccioná PCs para ver la vista previa</div>';
    return;
  }

  // PCs ya en destino
  var existing = (DB[toAula] || []).slice();
  // PCs que se van a mover
  var moving = selected.map(function(i){ return pcs[i]; });
  // Calcular nuevo N° para las que llegan
  var maxN = existing.length > 0 ? Math.max.apply(null, existing.map(function(p){ return p.n||0; })) : 0;
  var preview_pcs = existing.concat(moving.map(function(pc, i) {
    return Object.assign({}, pc, { n: maxN + i + 1 });
  }));

  preview.innerHTML = preview_pcs.map(function(pc) {
    var isNew = preview_pcs.indexOf(pc) >= existing.length;
    var cpu = (pc.cpu||'—').replace(/ with Radeon Graphics$/,'').replace(/ RADEON R7.*$/,'').replace(/ Radeon R5.*$/,'').replace(/ APU with.*$/,'').trim().slice(0,28);
    return '<div class="transfer-dest-item" style="'+(isNew?'background:rgba(79,124,255,.07);':'')+'">'+
      '<span class="transfer-dest-num">'+pc.n+'</span>'+
      '<span style="flex:1;font-size:11px;">'+cpu+'</span>'+
      (isNew ? '<span style="font-size:10px;color:var(--accent);font-weight:600;">NUEVO</span>' : '')+
    '</div>';
  }).join('');
}

function updateTransferSummary() {
  var fromAula = document.getElementById('transfer-from').value;
  var toAula   = document.getElementById('transfer-to').value;
  var n = getSelectedIndices().length;
  var summary = document.getElementById('transfer-summary');
  if (n === 0) { summary.classList.remove('show'); return; }
  summary.classList.add('show');
  summary.innerHTML = '&#128260; Se moverán <strong>'+n+' PC'+(n!==1?'s':'')+'</strong> de <strong>'+fromAula+'</strong> a <strong>'+toAula+'</strong>. Los números de PC se reasignarán automáticamente.';
}

function confirmTransfer() {
  var fromAula = document.getElementById('transfer-from').value;
  var toAula   = document.getElementById('transfer-to').value;
  if (fromAula === toAula) { toast('El aula origen y destino no pueden ser iguales', 'err'); return; }
  var selected = getSelectedIndices();
  if (selected.length === 0) { toast('Seleccioná al menos una PC', 'err'); return; }

  var pcs = DB[fromAula].slice();
  var moving = selected.map(function(i){ return pcs[i]; });
  // Quitar del origen
  DB[fromAula] = pcs.filter(function(_, i){ return selected.indexOf(i) === -1; });
  // Renumerar origen
  DB[fromAula].forEach(function(pc, i){ pc.n = i + 1; });
  // Agregar al destino con nuevos números
  if (!DB[toAula]) DB[toAula] = [];
  var maxN = DB[toAula].length > 0 ? Math.max.apply(null, DB[toAula].map(function(p){ return p.n||0; })) : 0;
  moving.forEach(function(pc, i) {
    var newPc = Object.assign({}, pc, { n: maxN + i + 1 });
    DB[toAula].push(newPc);
  });

  closeModal('modal-transfer');
  activeAula = fromAula;
  renderAll();
  saveToSheet(false);
  addHistory(
    'Traspaso: ' + moving.length + ' PC' + (moving.length!==1?'s':'') + ' de ' + fromAula + ' a ' + toAula,
    'PCs trasladadas: ' + moving.map(function(p){ return 'PC'+p.n; }).join(', '),
    'edit'
  );
  toast('Traspaso realizado correctamente', 'ok');
}

// ── USAGE TRACKING ──
var OR_DAILY_LIMIT = 200;
var OR_USAGE_KEY = 'ilm_or_usage_' + new Date().toDateString();

function getUsageToday() {
  try {
    var stored = sessionStorage.getItem(OR_USAGE_KEY);
    return stored ? parseInt(stored) : 0;
  } catch(e) { return 0; }
}

function addUsage(n) {
  try {
    var current = getUsageToday();
    sessionStorage.setItem(OR_USAGE_KEY, current + (n || 1));
    updateUsageBar();
  } catch(e) {}
}

function updateUsageBar() {
  var used = getUsageToday();
  var remaining = Math.max(0, OR_DAILY_LIMIT - used);
  var pct = (remaining / OR_DAILY_LIMIT) * 100;
  var fill = document.getElementById('usage-fill');
  var count = document.getElementById('usage-count');
  if (!fill || !count) return;
  fill.style.width = pct + '%';
  if (remaining > 100) {
    fill.className = 'usage-bar-fill';
    count.className = 'usage-bar-count ok';
    count.textContent = remaining + ' restantes';
  } else if (remaining > 20) {
    fill.className = 'usage-bar-fill warn';
    count.className = 'usage-bar-count warn';
    count.textContent = remaining + ' restantes';
  } else if (remaining > 0) {
    fill.className = 'usage-bar-fill warn';
    count.className = 'usage-bar-count warn';
    count.textContent = '⚠ Solo ' + remaining + ' restantes';
  } else {
    fill.className = 'usage-bar-fill warn';
    count.className = 'usage-bar-count empty';
    count.textContent = '✕ Límite diario alcanzado';
  }
}

