document.addEventListener('DOMContentLoaded', function() {
  var drop = document.getElementById('scan-drop');
  if (!drop) return;
  drop.addEventListener('dragover', function(e){ e.preventDefault(); this.classList.add('drag'); });
  drop.addEventListener('dragleave', function(){ this.classList.remove('drag'); });
  drop.addEventListener('drop', function(e){
    e.preventDefault(); this.classList.remove('drag');
    handleScanFiles(Array.from(e.dataTransfer.files));
  });
  document.getElementById('scan-file-input').addEventListener('change', function(){
    handleScanFiles(Array.from(this.files));
    this.value = '';
  });
});

function handleScanFiles(files) {
  files.forEach(function(f) {
    if (!f.type.startsWith('image/')) return;
    var idx = scanFiles.length;
    scanFiles.push(f);
    var reader = new FileReader();
    reader.onload = function(e) {
      var prev = document.getElementById('scan-previews');
      var div = document.createElement('div');
      div.className = 'scan-thumb';
      div.id = 'thumb-'+idx;
      div.innerHTML =
        '<img src="'+e.target.result+'">' +
        '<button class="scan-thumb-remove" onclick="removeScanFile('+idx+')">&#10005;</button>' +
        '<div class="scan-thumb-label">'+f.name.slice(0,12)+'</div>';
      prev.appendChild(div);
      updateScanCount();
    };
    reader.readAsDataURL(f);
  });
  document.getElementById('scan-analyze-btn').disabled = scanFiles.length === 0;
}

function updateScanCount() {
  var n = scanFiles.filter(Boolean).length;
  var lotes = Math.ceil(n / BATCH_SIZE);
  var statusArea = document.getElementById('scan-status-area');
  if (n > 0) {
    statusArea.innerHTML = '<div class="scan-status ok">'+
      '&#9989; '+n+' foto'+(n!==1?'s':'')+' cargada'+(n!==1?'s':'')+
      (lotes > 1 ? ' &middot; Se procesará en '+lotes+' lotes automáticos' : '')+
      '</div>';
  }
}

function removeScanFile(idx) {
  scanFiles[idx] = null;
  var thumb = document.getElementById('thumb-'+idx);
  if (thumb) thumb.remove();
  scanFiles = scanFiles.filter(Boolean);
  // Re-render
  var prev = document.getElementById('scan-previews');
  prev.innerHTML = '';
  scanFiles.forEach(function(f, i) {
    var reader = new FileReader();
    reader.onload = function(e) {
      var div = document.createElement('div');
      div.className = 'scan-thumb';
      div.innerHTML =
        '<img src="'+e.target.result+'">' +
        '<button class="scan-thumb-remove" onclick="removeScanFile('+i+')">&#10005;</button>' +
        '<div class="scan-thumb-label">'+f.name.slice(0,12)+'</div>';
      prev.appendChild(div);
    };
    reader.readAsDataURL(f);
  });
  document.getElementById('scan-analyze-btn').disabled = scanFiles.length === 0;
  updateScanCount();
}

function fileToBase64(file) {
  return new Promise(function(resolve, reject) {
    var r = new FileReader();
    r.onload = function(e) { resolve(e.target.result.split(',')[1]); };
    r.onerror = reject;
    r.readAsDataURL(file);
  });
}

function setScanStatus(area, msg, type) {
  var el = document.getElementById(area);
  if (!el) return;
  var icon = type === 'loading'
    ? '<div class="scan-spinner"></div>'
    : type === 'ok' ? '&#9989;' : '&#10060;';
  el.innerHTML = '<div class="scan-status '+type+'">'+icon+' '+msg+'</div>';
}

async function callGeminiBatch(files, batchNum, totalBatches) {
  var b64files = await Promise.all(files.map(fileToBase64));

  var prompt = `Sos un experto en leer capturas del Administrador de tareas de Windows (Task Manager). Las imágenes pueden ser fotos de celular a una pantalla de PC, por lo que pueden estar oscuras, borrosas o con ángulo. Hacé tu mejor esfuerzo para leer los datos.

Las imágenes son de PCs escolares. Pueden venir fotos de UNA O VARIAS PCs mezcladas. Tipos de fotos:
1. ETIQUETA física pegada en la PC (número de PC, ej: "PC 3", "204 - PC 3", "Aula 201 PC 5")
2. Pestaña CPU del Administrador de tareas (muestra modelo de CPU, velocidades, núcleos, caché)
3. Pestaña Memoria/RAM (muestra total de RAM, tipo, velocidad, ranuras, factor de forma)  
4. Pestaña Disco (muestra modelo de disco, tipo y capacidad)

INSTRUCCIONES IMPORTANTES:
- Si una imagen es borrosa, intentá leer lo que puedas igualmente
- Para el modelo de CPU: en la pestaña CPU aparece arriba a la derecha el nombre completo (ej: "AMD Ryzen 7 5700G with Radeon Graphics")
- Para RAM: el total aparece como "X,X GB" en uso de "Y,Y GB". El total Y es el que querés
- Para disco: el modelo aparece en la pestaña Disco del administrador
- Agrupá fotos de la misma PC usando las etiquetas o similitud de hardware
- Si claramente no podés leer un valor, usá "—". NO inventes valores

Para cada PC extraé exactamente estos campos:
{
  "pc_num": número de la etiqueta o null,
  "cpu": modelo completo del procesador,
  "vel_base": velocidad base GHz como string (ej: "3,80"),
  "vel_actual": velocidad actual GHz como string (ej: "4,23"),
  "nucleos": número entero de núcleos físicos,
  "proc_logicos": número entero de procesadores lógicos,
  "virtualizacion": "Habilitado" o "Deshabilitado",
  "cache_l1": string (ej: "512 kB"),
  "cache_l2": string (ej: "4,0 MB"),
  "cache_l3": string o "—",
  "ram_gb": número entero total de RAM en GB,
  "tipo_ram": "DDR3" o "DDR4" o "DDR5",
  "vel_ram": número entero velocidad en MHz,
  "ranuras": string (ej: "2 de 4"),
  "factor_forma": "DIMM" o "SO-DIMM",
  "disco_modelo": modelo completo del disco,
  "disco_tipo": "HDD" o "SSD (SATA)" o "SSD (NVMe)",
  "disco_cap": número entero capacidad en GB
}

Respondé ÚNICAMENTE con un array JSON válido. Sin texto, sin explicaciones, sin markdown, sin bloques de código. Solo el JSON puro.
Ejemplo de respuesta correcta: [{"pc_num":1,"cpu":"AMD Ryzen 7 5700G with Radeon Graphics",...}]`;

  var content = [{ type: 'text', text: prompt }];
  b64files.forEach(function(b64, i) {
    content.push({
      type: 'image_url',
      image_url: { url: 'data:' + files[i].type + ';base64,' + b64 }
    });
  });

  var lastError = null;
  for (var mi = 0; mi < OR_MODELS.length; mi++) {
    try {
      var res = await fetch(OR_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + OR_KEY,
          'HTTP-Referer': window.location.href,
          'X-Title': 'ILM Dashboard'
        },
        body: JSON.stringify({
          model: OR_MODELS[mi],
          messages: [{ role: 'user', content: content }]
        })
      });
      var data = await res.json();
      if (data.error) {
        lastError = data.error.message || JSON.stringify(data.error);
        continue; // try next model
      }
      var text = data.choices[0].message.content;
      text = text.replace(/```json\n?/g,'').replace(/```\n?/g,'').trim();
      var pcs = JSON.parse(text);
      addUsage(1);
      return Array.isArray(pcs) ? pcs : [pcs];
    } catch(e) {
      lastError = e.message;
    }
  }
  throw new Error('Ningún modelo disponible. Último error: ' + lastError);
}

async function analyzePhotos() {
  var validFiles = scanFiles.filter(Boolean);
  if (validFiles.length === 0) return;

  document.getElementById('scan-analyze-btn').disabled = true;

  var totalBatches = Math.ceil(validFiles.length / BATCH_SIZE);
  var allResults = [];
  var hasError = false;

  for (var b = 0; b < totalBatches; b++) {
    var start = b * BATCH_SIZE;
    var batch = validFiles.slice(start, start + BATCH_SIZE);
    setScanStatus('scan-status-area',
      'Procesando lote ' + (b+1) + ' de ' + totalBatches +
      ' (' + batch.length + ' fotos)...', 'loading');
    try {
      var batchResults = await callGeminiBatch(batch, b+1, totalBatches);
      allResults = allResults.concat(batchResults);
    } catch(e) {
      setScanStatus('scan-status-area', 'Error en lote '+(b+1)+': '+e.message, 'err');
      hasError = true;
      break;
    }
  }

  if (!hasError && allResults.length > 0) {
    // Ordenar por pc_num si existe
    allResults.sort(function(a,b) {
      var na = parseInt(a.pc_num) || 9999;
      var nb = parseInt(b.pc_num) || 9999;
      return na - nb;
    });
    scanResults = allResults;
    showScanResults(allResults);
  } else if (!hasError) {
    setScanStatus('scan-status-area', 'No se detectaron PCs en las fotos.', 'err');
    document.getElementById('scan-analyze-btn').disabled = false;
  }
}

