function saveScanResults() {
  var aula = document.getElementById('scan-aula-dest').value;
  if (!DB[aula]) DB[aula] = [];
  var saved = 0;

  scanResults.forEach(function(_, i) {
    var n = parseInt(document.getElementById('sr-n-'+i).value) || (DB[aula].length + 1);
    // Si ya existe una PC con ese número en el aula, la reemplazamos
    var existing = DB[aula].findIndex(function(p){ return p.n === n; });
    var pc = {
      n: n,
      estado: 'Operativa',
      cpu: document.getElementById('sr-cpu-'+i).value,
      vel_base: document.getElementById('sr-vb-'+i).value,
      vel_actual: document.getElementById('sr-va-'+i).value,
      nucleos: parseFloat(document.getElementById('sr-nc-'+i).value) || document.getElementById('sr-nc-'+i).value,
      proc_logicos: parseFloat(document.getElementById('sr-pl-'+i).value) || document.getElementById('sr-pl-'+i).value,
      virtualizacion: document.getElementById('sr-vt-'+i).value,
      cache_l1: document.getElementById('sr-c1-'+i).value,
      cache_l2: document.getElementById('sr-c2-'+i).value,
      cache_l3: document.getElementById('sr-c3-'+i).value,
      ram_gb: parseFloat(document.getElementById('sr-ram-'+i).value) || 0,
      tipo_ram: document.getElementById('sr-rt-'+i).value,
      vel_ram: parseFloat(document.getElementById('sr-rv-'+i).value) || 0,
      ranuras: document.getElementById('sr-rn-'+i).value,
      factor_forma: document.getElementById('sr-ff-'+i).value,
      disco_modelo: document.getElementById('sr-dm-'+i).value,
      disco_tipo: document.getElementById('sr-dt-'+i).value,
      disco_cap: parseFloat(document.getElementById('sr-dc-'+i).value) || 0,
      observaciones: ''
    };
    if (existing !== -1) {
      DB[aula][existing] = pc;
      addHistory('PC '+n+' actualizada en '+aula+' vía escaneo', 'CPU: '+(pc.cpu||'—'), 'edit');
    } else {
      DB[aula].push(pc);
      addHistory('PC '+n+' agregada en '+aula+' vía escaneo', 'CPU: '+(pc.cpu||'—'), 'add');
    }
    saved++;
  });

  // Ordenar PCs por número
  DB[aula].sort(function(a,b){ return (a.n||0)-(b.n||0); });

  closeScan();
  activeAula = aula;
  renderAll();
  saveToSheet(false);
  toast(saved + ' PC' + (saved!==1?'s':'') + ' guardada' + (saved!==1?'s':'') + ' correctamente', 'ok');
}
